package com.gomgomapps.math.core;
import java.util.*;import java.math.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaFractionDecimalTest {
 @Test public void allSelectedVisibleFractionsIgnoreHiddenKeys(){var limits=GlobalCurriculum.limits("na-nied-primary-2024-v1",FractionToDecimalCheck.ID,6);int count=0;for(int d:List.of(2,4,5,10,20,25,50,100))for(int n=0;n<=d;n++){Question q=ElementaryBasics.fractionDecimal(Catalog.get(FractionToDecimalCheck.ID),n,d);q.answers=new String[]{"999"};q.expression="999";assertTrue(limits.allows(q));String answer=BigDecimal.valueOf(n).divide(BigDecimal.valueOf(d)).toPlainString();if(!answer.contains("."))answer+=".0";assertTrue(new Checker().check(q,List.of(),List.of(answer)).correct());assertFalse(new Checker().check(q,List.of(),List.of(n+"/"+d)).correct());assertFalse(new Checker().check(q,List.of(),List.of(new BigDecimal(answer).add(BigDecimal.ONE).toPlainString())).correct());assertFalse(HelpPlan.forQuestion(q).canTransfer());count++;}assertEquals(224,count);}
 @Test public void publicInputContractAndMalformedConditions(){Question q=ElementaryBasics.fractionDecimal(Catalog.get(FractionToDecimalCheck.ID),1,5);q.answerFormat="number";q.answers[0]="9";assertTrue(new Checker().check(q,List.of(),List.of("0.20")).correct());assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("1/5")).status);for(String prompt:List.of("1/0의 값을 소수로 나타내세요.","1/3의 값을 소수로 나타내세요.","조건 없음"))assertNull(FractionToDecimalCheck.read(new Question(q.skillId,prompt,"0.2","0.2")));Question reduced=new Question(q.skillId,"3/6의 값을 소수로 나타내세요.","poison","poison");assertTrue(new Checker().check(reduced,List.of(),List.of("0.5")).correct());}
 @Test public void normalNaSixFreshAllDenominatorsAndZeroWhole(){var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals("na-nied-primary-2024-v1")).findFirst().orElseThrow();assertTrue(pack.inGrade(FractionToDecimalCheck.ID,6));var limits=GlobalCurriculum.limits(pack.id,FractionToDecimalCheck.ID,6);Generator g=new Generator(new Random(286));List<String> recent=new ArrayList<>();Set<Integer> den=new HashSet<>();boolean zero=false,one=false;for(int i=0;i<224;i++){Question q=g.next(FractionToDecimalCheck.ID,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());String[] raw=q.prompt.substring(0,q.prompt.indexOf('의')).split("/");den.add(Integer.parseInt(raw[1]));Rational v=FractionToDecimalCheck.read(q);assertNotNull(v);zero|=v.equals(Rational.ZERO);one|=v.equals(Rational.ONE);assertTrue(limits.allows(q));String answer=v.decimalText();if(!answer.contains("."))answer+=".0";assertTrue(new Checker().check(q,List.of(),List.of(answer)).correct());}assertEquals(Set.of(2,4,5,10,20,25,50,100),den);assertTrue(zero);assertTrue(one);assertEquals(recent.get(0),g.next(FractionToDecimalCheck.ID,recent,false,limits).signature());}
}
